package io.github.ningpp.compat;

/** Replacement for System.Diagnostics.Eventing.Reader.EventLogReadingException (generated by CSharpToJava converter). */
public class EventLogReadingException extends EventLogException {
    public EventLogReadingException() { super(); }
    public EventLogReadingException(String message) { super(message); }
    public EventLogReadingException(String message, Throwable cause) { super(message, cause); }
}
